/** Optional browsing companion. No catalogue calls until the user connects their own TMDB key. */
public final class DiscoverActivity extends PanelActivity {
    String kind="movie",query="",provider="",genre="",genreName="All genres";int rating=0,sort=0,browsePage=1;boolean landing;
    @Override public void onCreate(android.os.Bundle b){super.onCreate(b);var p=DiscoverStore.prefs(this);kind=p.getString("browse-kind","movie");if(!kind.equals("tv"))kind="movie";provider=p.getString("browse-provider","");if(!Arrays.asList(PROVIDERS).contains(provider))provider="";readGenre();rating=Math.max(0,Math.min(8,p.getInt("rating",0)));sort=Math.max(0,Math.min(2,p.getInt("sort",0)));}
    void readGenre(){var p=DiscoverStore.prefs(this);genre=p.getString("genre-"+kind,"");if(!genre.matches("[1-9][0-9]{0,6}"))genre="";genreName=genre.isEmpty()?"All genres":p.getString("genre-name-"+kind,"Selected genre");}
    static final String[] SERVICES={"All titles","Netflix","Prime Video","Crunchyroll","Apple TV+","Disney+"};
    static final String[] PROVIDERS={"","8","9","283","350","337"};
    @Override void home(){landing=true;page("Discover","A catalogue and watchlist, separate from Home. Titles and availability come from TMDB; playback belongs to your streaming apps.",false);button("Connection & region",this::configure);button("About & data credits",this::credits);button("Your watchlist",this::watchlist);
        if(!DiscoverStore.prefs(this).getBoolean("enabled",false)){page.addView(text("Not connected. Add your own TMDB read token whenever you want online browsing. No request has been made.",18));return;}
        button("Browse filters · "+genreName+" · "+DiscoverFilters.SORTS[sort],this::filters);button("Search titles",this::search);
        TextView status=text(query.isEmpty()?"Loading page "+browsePage+"…":"Searching all titles. Genre, rating and service filters apply to Browse; check availability in each title.",17);page.addView(status);
        Map<String,String> p=DiscoverFilters.params(kind,DiscoverStore.prefs(this).getString("region","US"),Locale.getDefault().toLanguageTag(),provider,genre,rating,sort,browsePage,query,new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.ROOT).format(new Date()));
        load(()->DiscoverStore.request(this,query.isEmpty()?"discover/"+kind:"search/multi",p),data->{status.setText((data.optBoolean("dv_saved")?"Saved catalogue · ":"")+(query.isEmpty()?"Page "+browsePage+" · availability may change.":"Search across services · check availability in title details."));render(data.optJSONArray("results"));if(browsePage>1)button("Previous page",()->{browsePage--;home();});if(browsePage<Math.min(20,data.optInt("total_pages",1)))button("Next page",()->{browsePage++;home();});},bad->status.setText("Catalogue unavailable. Check the key, region and connection. Your watchlist remains available."));
    }
    void filters(){
        landing=false;page("Browse filters","Apply a draft to browse. Search has its own results; availability is checked in title details. Top rated requires at least 100 votes.",false);
        String[] k={kind},pr={provider},g={genre},gn={genreName};int[] r={rating},so={sort};
        TextView type=button("Type · "+(k[0].equals("movie")?"Movies":"TV series"),()->{});type.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Type").setItems(new String[]{"Movies","TV series"},(d,n)->{k[0]=n==0?"movie":"tv";g[0]="";gn[0]="All genres";type.setText("Type · "+(n==0?"Movies":"TV series"));}).setNegativeButton("Cancel",null).show());
        TextView service=button("Service · "+SERVICES[Arrays.asList(PROVIDERS).indexOf(pr[0])],()->{});service.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Your service").setItems(SERVICES,(d,n)->{pr[0]=PROVIDERS[n];service.setText("Service · "+SERVICES[n]);}).setNegativeButton("Cancel",null).show());
        TextView genres=button("Genre · "+gn[0],()->{});genres.setOnClickListener(v->{String requestedKind=k[0];genres.setText("Loading genres…");load(()->DiscoverStore.request(this,"genre/"+requestedKind+"/list",Collections.singletonMap("language",Locale.getDefault().toLanguageTag())),data->{if(!requestedKind.equals(k[0])){genres.setText("Genre · "+gn[0]);return;}java.util.List<String> ids=new ArrayList<>(),labels=new ArrayList<>();ids.add("");labels.add("All genres");JSONArray a=data.optJSONArray("genres");for(int i=0;a!=null&&i<Math.min(40,a.length());i++){JSONObject x=a.optJSONObject(i);if(x!=null&&x.optInt("id")>0&&x.optString("name").length()<=80){ids.add(String.valueOf(x.optInt("id")));labels.add(x.optString("name"));}}genres.setText("Genre · "+gn[0]);new AlertDialog.Builder(this).setTitle("Genre").setItems(labels.toArray(new String[0]),(d,n)->{g[0]=ids.get(n);gn[0]=labels.get(n);genres.setText("Genre · "+gn[0]);}).setNegativeButton("Cancel",null).show();},bad->genres.setText("Genres unavailable · try again"));});
        TextView score=button("Minimum rating · "+(r[0]==0?"Any":r[0]+" / 10"),()->{});score.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Minimum rating").setItems(new String[]{"Any","6 / 10","7 / 10","8 / 10"},(d,n)->{r[0]=new int[]{0,6,7,8}[n];score.setText("Minimum rating · "+(r[0]==0?"Any":r[0]+" / 10"));}).setNegativeButton("Cancel",null).show());
        TextView order=button("Order · "+DiscoverFilters.SORTS[so[0]],()->{});order.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Order").setItems(DiscoverFilters.SORTS,(d,n)->{so[0]=n;order.setText("Order · "+DiscoverFilters.SORTS[n]);}).setNegativeButton("Cancel",null).show());
        button("Apply filters",()->{kind=k[0];provider=pr[0];genre=g[0];genreName=gn[0];rating=r[0];sort=so[0];query="";browsePage=1;DiscoverStore.prefs(this).edit().putString("browse-kind",kind).putString("browse-provider",provider).putString("genre-"+kind,genre).putString("genre-name-"+kind,genreName).putInt("rating",rating).putInt("sort",sort).apply();home();});button("Cancel",this::home);
    }

    void credits(){landing=false;page("About DV Freedom Discover","Optional catalogue browsing and a TV-local watchlist. No connection to your streaming accounts.",false);ImageView logo=new ImageView(this);logo.setImageResource(R.drawable.tmdb_mark);logo.setContentDescription("The Movie Database (TMDB)");logo.setScaleType(ImageView.ScaleType.FIT_START);page.addView(logo,new LinearLayout.LayoutParams(dp(154),dp(20)));page.addView(text("This product uses the TMDB API but is not endorsed or certified by TMDB.",17));page.addView(text("Streaming availability data is provided by JustWatch through TMDB. Availability can change; verify in the service before subscribing or paying. themoviedb.org · justwatch.com",17));button("Back",this::home);}
    void configure(){landing=false;var p=DiscoverStore.prefs(this);page("Connect Discover","Optional. TMDB receives catalogue queries, region and your API key; image requests go to TMDB. No streaming credentials, viewing history or TV inventory are uploaded. This product uses the TMDB API but is not endorsed or certified by TMDB. Availability data: JustWatch.",true);EditText key=field("TMDB v4 read token or v3 API key",p.getString("key",""),true),region=field("Two-letter region, e.g. US or GB",p.getString("region","US"),false);button("Save and enable browsing",()->{String k=key.getText().toString().trim(),r=region.getText().toString().trim().toUpperCase(Locale.ROOT);if(!DiscoverStore.key(k)||!DiscoverStore.region(r)){Toast.makeText(this,"Check the read token and region",Toast.LENGTH_LONG).show();return;}DiscoverStore.clear(this);p.edit().putString("key",k).putString("region",r).putBoolean("enabled",true).apply();home();});button("Disconnect & forget key",()->{p.edit().remove("key").putBoolean("enabled",false).apply();DiscoverStore.clear(this);home();});button("Back",this::home);}
    void search(){EditText input=new EditText(this);input.setSingleLine(true);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(120)});new AlertDialog.Builder(this).setTitle("Search movies and TV").setView(input).setPositiveButton("Search",(d,w)->{query=input.getText().toString().trim();browsePage=1;home();}).setNegativeButton("Cancel",null).show();}
    void render(JSONArray results){if(results==null||results.length()==0){page.addView(text("No matching titles. Try another service or search.",18));return;}GridLayout grid=new GridLayout(this);grid.setColumnCount(getResources().getConfiguration().screenWidthDp<700?2:3);page.addView(grid);int count=0;
        for(int i=0;i<results.length()&&count<18;i++){JSONObject item=results.optJSONObject(i);if(item==null)continue;try{DiscoverStore.token(item);}catch(RuntimeException notTitle){continue;}if(item.optBoolean("adult"))continue;count++;LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(dp(12),dp(10),dp(12),dp(10));card.setFocusable(true);card.setClickable(true);card.setBackgroundResource(R.drawable.freedom_action);ImageView art=new ImageView(this);art.setScaleType(ImageView.ScaleType.CENTER_CROP);card.addView(art,new LinearLayout.LayoutParams(dp(210),dp(110)));TextView label=text(DiscoverStore.title(item),18);label.setMaxLines(2);label.setTextColor(new android.content.res.ColorStateList(new int[][]{new int[]{android.R.attr.state_focused},new int[0]},new int[]{0xff182334,-1}));card.setOnFocusChangeListener((v,on)->label.setTextColor(on?0xff182334:-1));card.addView(label);card.setContentDescription(DiscoverStore.title(item));card.setOnClickListener(v->details(item));GridLayout.LayoutParams lp=new GridLayout.LayoutParams();lp.width=dp(234);lp.height=dp(194);lp.setMargins(0,0,dp(12),dp(12));grid.addView(card,lp);String path=item.optString("backdrop_path");if(!path.matches("/[A-Za-z0-9._-]+"))path=item.optString("poster_path");if(path.matches("/[A-Za-z0-9._-]+")){String url="https://image.tmdb.org/t/p/w300"+path;load(()->Network.request(url,null,null,false,512*1024),bytes->{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(o.outWidth>0&&o.outHeight>0&&(long)o.outWidth*o.outHeight<1000000){o.inJustDecodeBounds=false;Bitmap b=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);art.setImageBitmap(b);}},bad->{});}}
    }
    void details(JSONObject item){landing=false;String token=DiscoverStore.token(item);page(DiscoverStore.title(item),item.optString("overview","No description available."),false);page.addView(text("Rating "+item.optDouble("vote_average",0)+" / 10 · "+item.optString("release_date",item.optString("first_air_date","")),17));boolean saved=watch().has(token);button(saved?"Remove from watchlist":"Save to watchlist",()->{JSONObject w=watch();try{if(w.has(token))w.remove(token);else if(w.length()<100)w.put(token,item);else throw new IllegalArgumentException();String value=w.toString();if(value.length()>262144)throw new IllegalArgumentException();DiscoverStore.prefs(this).edit().putString("watchlist",value).apply();details(item);}catch(Exception full){Toast.makeText(this,"Watchlist is full",Toast.LENGTH_LONG).show();}});
        TextView status=text("Checking services in your selected region…",17);page.addView(status);load(()->DiscoverStore.request(this,token+"/watch/providers",Collections.emptyMap()),data->{JSONObject all=data.optJSONObject("results"),region=all==null?null:all.optJSONObject(DiscoverStore.prefs(this).getString("region","US"));JSONArray flat=region==null?null:region.optJSONArray("flatrate");status.setText(data.optBoolean("dv_saved")?"Saved availability · verify in the app":"Subscription availability from JustWatch via TMDB. May be incomplete or out of date.");if(flat==null||flat.length()==0)page.addView(text("No subscription availability reported for this region.",17));else for(int i=0;i<Math.min(8,flat.length());i++){JSONObject service=flat.optJSONObject(i);if(service!=null)serviceButton(service.optString("provider_name"),item);}},bad->status.setText("Service availability unavailable. Use your streaming app’s search."));button("Back to catalogue",this::home);}
    void serviceButton(String label,JSONObject item){String pkg=ServiceLinks.pkg(label);if(pkg==null)return;String title=DiscoverStore.title(item),key="link/"+DiscoverStore.token(item)+"/"+pkg;var prefs=DiscoverStore.prefs(this);String saved=prefs.getString(key,"");
        Intent search=new Intent(Intent.ACTION_SEARCH).setPackage(pkg).putExtra(android.app.SearchManager.QUERY,title);Intent launch=getPackageManager().getLeanbackLaunchIntentForPackage(pkg);boolean canSearch=getPackageManager().resolveActivity(search,0)!=null;
        if(canSearch||launch!=null)button((canSearch?"Search ":"Open ")+label,()->{try{startActivity(canSearch?search:launch);}catch(RuntimeException absent){Toast.makeText(this,"Open the service and search for this title",Toast.LENGTH_LONG).show();}});
        if(!saved.isEmpty())try{Intent direct=new Intent(Intent.ACTION_VIEW,Uri.parse(ServiceLinks.validate(pkg,saved))).setPackage(pkg);if(getPackageManager().resolveActivity(direct,0)!=null)button("Open saved title link · "+label,()->{try{startActivity(direct);}catch(RuntimeException absent){Toast.makeText(this,"Title link unavailable. Use service search.",Toast.LENGTH_LONG).show();}});}catch(IllegalArgumentException ignored){}
        button("Title link options · "+label,()->{EditText input=new EditText(this);input.setSingleLine(true);input.setText(saved);input.setHint("HTTPS title link, without tracking parameters");new AlertDialog.Builder(this).setTitle("Your title link · "+label).setMessage("Optional. Paste the service’s link for this title. It opens only in that installed app; playback and region availability are not guaranteed. Saved on this TV only.").setView(input).setPositiveButton("Save",(d,n)->{try{String url=ServiceLinks.validate(pkg,input.getText().toString().trim());int count=0;for(String name:prefs.getAll().keySet())if(name.startsWith("link/"))count++;if(saved.isEmpty()&&count>=100)throw new IllegalArgumentException("Title-link limit reached");prefs.edit().putString(key,url).apply();details(item);}catch(IllegalArgumentException bad){Toast.makeText(this,bad.getMessage(),Toast.LENGTH_LONG).show();}}).setNeutralButton("Remove",(d,n)->{prefs.edit().remove(key).apply();details(item);}).setNegativeButton("Cancel",null).show();});
    }
    JSONObject watch(){try{String raw=DiscoverStore.prefs(this).getString("watchlist","{}");if(raw.length()>262144)throw new IllegalArgumentException();return new JSONObject(raw);}catch(Exception bad){return new JSONObject();}}
    void watchlist(){landing=false;page("Your watchlist","Stored in this companion on this TV. It is separate from streaming-service accounts.",true);JSONObject w=watch();if(w.length()==0)page.addView(text("Save a title from Discover to find it here.",18));for(Iterator<String> it=w.keys();it.hasNext();){JSONObject item=w.optJSONObject(it.next());if(item!=null)button(DiscoverStore.title(item),()->details(item));}button("Back",this::home);}
    @Override public void onBackPressed(){if(landing)finish();else home();}
}
